<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_login();if(!user_has_any_permission($user,['ACLARACION_CREAR','ACLARACION_GESTIONAR']))json_response(['ok'=>false,'error'=>'Sin permiso para aclaraciones'],403);$movementId=(int)($_GET['movimiento_id']??0);$status=strtoupper(trim((string)($_GET['estatus']??'')));$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$ids=visible_department_ids($db,$user);if(!$ids){$db->close();json_response(['ok'=>true,'data'=>[]]);}$where=['pm.departamento_id IN ('.implode(',',array_map('intval',$ids)).')'];if($movementId>0)$where[]='a.movimiento_id='.(int)$movementId;if(in_array($status,['ABIERTA','EN_REVISION','RESUELTA','CERRADA'],true))$where[]="a.estatus='".$db->real_escape_string($status)."'";$sql="SELECT a.*,pm.folio movimiento_folio,pm.departamento_id,pm.solicitado_por_usuario_id,pm.otorgado_a_usuario_id,pm.registrado_por_usuario_id,d.nombre departamento,CONCAT_WS(' ',uc.nombre,uc.apellido_paterno,uc.apellido_materno) creada_por,CONCAT_WS(' ',ua.nombre,ua.apellido_paterno,ua.apellido_materno) asignada_a,(SELECT COUNT(*) FROM movimiento_aclaracion_mensaje m WHERE m.aclaracion_id=a.aclaracion_id) mensajes_count FROM movimiento_aclaracion a JOIN presupuesto_movimiento pm ON pm.movimiento_id=a.movimiento_id JOIN departamento d ON d.departamento_id=pm.departamento_id JOIN usuario uc ON uc.usuario_id=a.creada_por_usuario_id LEFT JOIN usuario ua ON ua.usuario_id=a.asignada_a_usuario_id WHERE ".implode(' AND ',$where)." ORDER BY FIELD(a.estatus,'ABIERTA','EN_REVISION','RESUELTA','CERRADA'),a.updated_at DESC";$rs=$db->query($sql);$data=[];while($r=$rs->fetch_assoc()){if(!movement_is_visible($db,$user,$r))continue;$r['aclaracion_id']=(int)$r['aclaracion_id'];$r['movimiento_id']=(int)$r['movimiento_id'];$r['mensajes_count']=(int)$r['mensajes_count'];$data[]=$r;}$db->close();json_response(['ok'=>true,'data'=>$data]);
